by_path[project_hub]["updated_at"] = stamp

questions = [
    ("Why begin a new CSP in report-only mode?", ["Observe legitimate violations before blocking users", "Guarantee all scripts are safe", "Avoid checking application journeys"], "Report-only mode supports a measured rollout."),
    ("A CSP report contains a query path. What should storage do?", ["Redact sensitive fields and restrict retention", "Store every raw body forever", "Publish it in a public dashboard"], "Reports can carry user-controlled or sensitive data."),
    ("Static CSS has the expected header, but generated HTML does not. Where is the gap?", ["The generated response producer", "The CSS bundle", "The author's CMS draft"], "Header coverage follows the response path."),
    ("What does a credentialed CORS response require?", ["A validated specific origin and credential permission", "A wildcard allowed origin", "No server authorization"], "Browsers reject wildcard origin with credentials."),
    ("Why vary an allowed-origin response by Origin?", ["Prevent a shared cache from serving another origin's policy", "Make the CMS record public", "Remove preflight latency"], "An origin-specific policy is part of the cached response."),
    ("Does CORS authorize an editor to publish?", ["No; the API must separately check the session and permission", "Yes, if the origin is listed", "Yes, if the cookie is Secure"], "CORS controls browser response access, not the business operation."),
    ("When is parent includeSubDomains appropriate?", ["After every affected hostname has working HTTPS and an owner", "After the main homepage loads", "Before inventorying delegated hosts"], "The policy reaches beyond one application host."),
    ("Why is HSTS rollback slower than an artifact rollback?", ["Browsers can retain the transport policy until it expires", "The HTML build has more files", "The CMS webhook may repeat"], "Client-held policy outlives a deployment switch."),
    ("A WAF rule blocks a legitimate editor form. What is the narrow repair?", ["An exception for the identified rule and route with expiry", "Disable every managed rule", "Bypass all authenticated traffic forever"], "The exception should preserve unrelated protections."),
    ("Which signal finds a WAF false positive?", ["Rule matches joined with failed legitimate journeys", "Total blocked requests alone", "Only origin CPU load"], "An edge block may never reach the application."),
    ("What proves a header policy reached a public page?", ["A response probe through the public hostname for that route class", "A configuration file in the repository", "A successful local build"], "Delivery evidence comes from the actual response."),
    ("What should a policy rollback verify?", ["The affected user paths pass after the previous policy returns", "Only that block counts decrease", "Only that the homepage loads"], "Recovery is a user-path result."),
]
